package org.novasos.healthysv2.maternalandchildhealth;
import static org.novasos.healthysv2.maternalandchildhealth.api.MaternalChildDtos.*;import java.util.*;import org.novasos.healthysv2.patient.PatientAccessService;import org.novasos.healthysv2.shared.api.error.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Service @Transactional class MaternalChildService{
 private final PregnancyRepository pregnancies;private final ChildHealthRecordRepository records;private final JdbcTemplate jdbc;private final PatientAccessService access;MaternalChildService(PregnancyRepository pregnancies,ChildHealthRecordRepository records,JdbcTemplate jdbc,PatientAccessService access){this.pregnancies=pregnancies;this.records=records;this.jdbc=jdbc;this.access=access;}
 PregnancyResponse start(StartPregnancyRequest r){access.requireAccess(r.motherPatientId(),"MATERNAL_HEALTH","WRITE");require("patient.patient",r.motherPatientId(),"Patient");if(exists("select count(*) from maternal_child.pregnancy where mother_patient_id=? and status='ACTIVE'",r.motherPatientId()))throw new ConflictException("ACTIVE_PREGNANCY_EXISTS","error.maternal.pregnancy-active");try{var p=Pregnancy.start(r.motherPatientId(),r.estimatedConceptionDate(),r.lastMenstrualPeriod(),r.expectedDeliveryDate());pregnancies.saveAndFlush(p);audit(p.getMotherPatientId(),null,"Pregnancy",p.getId(),"START_PREGNANCY",p.getStatus());return response(p);}catch(IllegalArgumentException e){throw rule("INVALID_PREGNANCY_DATES","error.maternal.pregnancy-dates");}}
 @Transactional(readOnly=true)List<PregnancySummary>search(UUID mother){if(mother==null)throw rule("MOTHER_REQUIRED","error.maternal.patient-mismatch");access.requireAccess(mother,"MATERNAL_HEALTH","READ");return pregnancies.findByMotherPatientIdOrderByCreatedAtDesc(mother).stream().map(this::summary).toList();}
 @Transactional(readOnly=true)PregnancyResponse find(UUID id){var p=get(id);access.requireAccess(p.getMotherPatientId(),"MATERNAL_HEALTH","READ");return response(p);}
 PrenatalVisitResponse addVisit(UUID id,PrenatalVisitRequest r){var p=write(id);if(r.consultationId()!=null&&!exists("select count(*) from consultation.consultation where id=? and patient_id=?",r.consultationId(),p.getMotherPatientId()))throw rule("CONSULTATION_PATIENT_MISMATCH","error.maternal.patient-mismatch");if(r.professionalId()!=null)require("professional.professional",r.professionalId(),"Professional");try{var v=p.addVisit(r.consultationId(),r.professionalId(),r.visitDate(),r.gestationalAgeWeeks(),r.weight(),r.systolicPressure(),r.diastolicPressure(),r.fetalHeartRate(),r.notes());pregnancies.flush();audit(p.getMotherPatientId(),null,"Pregnancy",p.getId(),"ADD_PRENATAL_VISIT",p.getStatus());return visit(v);}catch(IllegalStateException e){throw inactive();}}
 PregnancyRiskResponse addRisk(UUID id,PregnancyRiskRequest r){var p=write(id);try{var risk=p.addRisk(r.riskType(),r.severity(),r.notes());pregnancies.flush();audit(p.getMotherPatientId(),null,"Pregnancy",p.getId(),"ADD_RISK",p.getStatus());return risk(risk);}catch(IllegalStateException e){throw inactive();}}
 PregnancyRiskResponse resolveRisk(UUID id,UUID riskId){var p=write(id);try{p.resolveRisk(riskId);pregnancies.flush();audit(p.getMotherPatientId(),null,"Pregnancy",p.getId(),"RESOLVE_RISK",p.getStatus());return p.getRisks().stream().filter(x->x.getId().equals(riskId)).map(this::risk).findFirst().orElseThrow();}catch(NoSuchElementException e){throw notFound("PregnancyRisk",riskId);}catch(IllegalStateException e){throw inactive();}}
 DeliveryResponse deliver(UUID id,DeliveryRequest r){var p=write(id);if(r.organizationId()!=null)require("organization.organization",r.organizationId(),"Organization");if(r.professionalId()!=null)require("professional.professional",r.professionalId(),"Professional");for(var n:r.newborns())require("patient.patient",n.childPatientId(),"Patient");try{var data=r.newborns().stream().map(n->new Pregnancy.NewbornData(n.childPatientId(),n.birthOrder(),n.birthWeight(),n.birthHeight(),n.headCircumference(),n.apgar1(),n.apgar5())).toList();var delivery=p.deliver(r.organizationId(),r.deliveryDate(),r.deliveryType(),r.professionalId(),r.complications(),r.notes(),data);pregnancies.flush();for(var n:delivery.getNewborns()){if(records.existsByChildPatientId(n.getChildPatientId()))throw new ConflictException("CHILD_RECORD_EXISTS","error.maternal.patient-mismatch");records.save(ChildHealthRecord.open(n.getChildPatientId(),p.getMotherPatientId()));}records.flush();audit(p.getMotherPatientId(),r.organizationId(),"Delivery",delivery.getId(),"REGISTER_DELIVERY",p.getStatus());return delivery(delivery);}catch(DataIntegrityViolationException e){throw new ConflictException("DELIVERY_OR_CHILD_EXISTS","error.maternal.delivery-exists");}catch(IllegalStateException e){throw new ConflictException("DELIVERY_EXISTS_OR_PREGNANCY_CLOSED","error.maternal.delivery-exists");}}
 PostpartumVisitResponse addPostpartum(UUID id,PostpartumVisitRequest r){var p=get(id);access.requireAccess(p.getMotherPatientId(),"MATERNAL_HEALTH","WRITE");if(r.professionalId()!=null)require("professional.professional",r.professionalId(),"Professional");try{var v=p.addPostpartumVisit(p.getMotherPatientId(),r.professionalId(),r.visitDate(),r.notes(),r.status());pregnancies.flush();audit(p.getMotherPatientId(),null,"Pregnancy",p.getId(),"ADD_POSTPARTUM_VISIT",p.getStatus());return postpartum(v);}catch(IllegalStateException e){throw rule("DELIVERY_REQUIRED","error.maternal.delivery-exists");}}
 @Transactional(readOnly=true)ChildHealthRecordResponse childRecord(UUID child){var record=record(child);requireChildAccess(record,"READ");return childResponse(record);}
 VaccinationResponse vaccinate(UUID child,VaccinationRequest r){var record=record(child);requireChildAccess(record,"WRITE");require("catalog.vaccine_catalog",r.vaccineCatalogId(),"VaccineCatalog");if(r.administeredBy()!=null)require("professional.professional",r.administeredBy(),"Professional");if(r.organizationId()!=null)require("organization.organization",r.organizationId(),"Organization");try{var v=record.addVaccination(r.vaccineCatalogId(),r.doseNumber(),r.administeredAt(),r.administeredBy(),r.organizationId(),r.batchNumber(),r.nextDueDate(),r.status());records.flush();audit(child,r.organizationId(),"Vaccination",v.getId(),"ADD_VACCINATION",v.getStatus());return vaccination(v);}catch(DataIntegrityViolationException e){throw new ConflictException("VACCINATION_EXISTS","error.maternal.vaccination-exists");}}
 GrowthMeasurementResponse measure(UUID child,GrowthMeasurementRequest r){var record=record(child);requireChildAccess(record,"WRITE");if(r.measuredBy()!=null)require("professional.professional",r.measuredBy(),"Professional");try{var m=record.addMeasurement(r.measuredAt(),r.weight(),r.height(),r.headCircumference(),r.measuredBy());records.flush();audit(child,null,"GrowthMeasurement",m.getId(),"ADD_GROWTH_MEASUREMENT","RECORDED");return growth(m);}catch(IllegalArgumentException e){throw rule("GROWTH_VALUE_REQUIRED","error.maternal.growth-values");}}
 private Pregnancy write(UUID id){var p=get(id);access.requireAccess(p.getMotherPatientId(),"MATERNAL_HEALTH","WRITE");return p;}private Pregnancy get(UUID id){return pregnancies.findDetailed(id).orElseThrow(()->notFound("Pregnancy",id));}private ChildHealthRecord record(UUID child){return records.findByChildPatientId(child).orElseThrow(()->notFound("ChildHealthRecord",child));}private void requireChildAccess(ChildHealthRecord record,String action){try{access.requireAccess(record.getChildPatientId(),"PEDIATRIC_RECORD",action);}catch(AccessDeniedException denied){if(record.getMotherPatientId()==null)throw denied;access.requireAccess(record.getMotherPatientId(),"PEDIATRIC_RECORD",action);}}private void require(String table,UUID id,String resource){if(!exists("select count(*) from "+table+" where id=?",id))throw notFound(resource,id);}private boolean exists(String sql,Object...args){return Objects.requireNonNull(jdbc.queryForObject(sql,Integer.class,args))>0;}
 private PregnancySummary summary(Pregnancy p){return new PregnancySummary(p.getId(),p.getNumber(),p.getMotherPatientId(),p.getExpectedDeliveryDate(),p.getStatus(),p.getCreatedAt());}private PregnancyResponse response(Pregnancy p){return new PregnancyResponse(p.getId(),p.getNumber(),p.getMotherPatientId(),p.getConceptionDate(),p.getLastMenstrualPeriod(),p.getExpectedDeliveryDate(),p.getStatus(),p.getCreatedAt(),p.getVisits().stream().map(this::visit).toList(),p.getRisks().stream().map(this::risk).toList(),p.getDelivery()==null?null:delivery(p.getDelivery()),p.getPostpartumVisits().stream().map(this::postpartum).toList());}private PrenatalVisitResponse visit(PrenatalVisit v){return new PrenatalVisitResponse(v.getId(),v.getConsultationId(),v.getProfessionalId(),v.getVisitDate(),v.getGestationalAgeWeeks(),v.getWeight(),v.getSystolicPressure(),v.getDiastolicPressure(),v.getFetalHeartRate(),v.getNotes());}private PregnancyRiskResponse risk(PregnancyRisk r){return new PregnancyRiskResponse(r.getId(),r.getType(),r.getSeverity(),r.getIdentifiedAt(),r.getNotes(),r.getStatus());}private DeliveryResponse delivery(Delivery d){return new DeliveryResponse(d.getId(),d.getOrganizationId(),d.getDeliveryDate(),d.getType(),d.getProfessionalId(),d.getComplications(),d.getNotes(),d.getNewborns().stream().map(this::newbornResponse).toList());}private NewbornResponse newbornResponse(Newborn n){return new NewbornResponse(n.getId(),n.getChildPatientId(),n.getBirthOrder(),n.getBirthWeight(),n.getBirthHeight(),n.getHeadCircumference(),n.getApgar1(),n.getApgar5(),n.getStatus());}private PostpartumVisitResponse postpartum(PostpartumVisit v){return new PostpartumVisitResponse(v.getId(),v.getProfessionalId(),v.getVisitDate(),v.getNotes(),v.getStatus());}
 private ChildHealthRecordResponse childResponse(ChildHealthRecord r){return new ChildHealthRecordResponse(r.getId(),r.getChildPatientId(),r.getMotherPatientId(),r.getCreatedAt(),r.getStatus(),r.getVaccinations().stream().map(this::vaccination).toList(),r.getMeasurements().stream().map(this::growth).toList());}private VaccinationResponse vaccination(Vaccination v){String[] catalog=jdbc.query("select code,name from catalog.vaccine_catalog where id=?",rs->rs.next()?new String[]{rs.getString(1),rs.getString(2)}:new String[]{null,null},v.getVaccineCatalogId());return new VaccinationResponse(v.getId(),v.getVaccineCatalogId(),catalog[0],catalog[1],v.getDoseNumber(),v.getAdministeredAt(),v.getAdministeredBy(),v.getOrganizationId(),v.getBatchNumber(),v.getNextDueDate(),v.getStatus());}private GrowthMeasurementResponse growth(GrowthMeasurement m){return new GrowthMeasurementResponse(m.getId(),m.getMeasuredAt(),m.getWeight(),m.getHeight(),m.getHeadCircumference(),m.getBmi(),m.getMeasuredBy());}
 private void audit(UUID patient,UUID organization,String type,UUID entity,String action,String status){jdbc.update("insert into audit.audit_log(actor_person_id,organization_id,module,entity_type,entity_id,action,new_value) values (?,?,?,?,?,?,?::jsonb)",actor(),organization,"MATERNAL_CHILD",type,entity,action,"{\"patientId\":\""+patient+"\",\"status\":\""+status+"\"}");}private UUID actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(!(a instanceof JwtAuthenticationToken jwt))return null;try{UUID sub=UUID.fromString(jwt.getToken().getSubject());return jdbc.query("select id from identity.person where keycloak_user_id=? or id=? limit 1",rs->rs.next()?(UUID)rs.getObject(1):null,sub,sub);}catch(IllegalArgumentException e){return null;}}
 private BusinessRuleException inactive(){return rule("PREGNANCY_NOT_ACTIVE","error.maternal.pregnancy-active");}private ResourceNotFoundException notFound(String r,Object id){return new ResourceNotFoundException(r,id);}private BusinessRuleException rule(String code,String key){return new BusinessRuleException(code,key);}
}
